{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "The closest analogue, ginsenoside Rg3 (Morgan similarity 0.7952), shares the same protopanaxadiol triterpene scaffold and sugar attachment pattern; a human pharmacokinetic study reported low oral bioavailability of Rg3 after oral administration, directly supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Glycyrrhizin, a large triterpenoid diglycoside, has an absolute oral bioavailability of approximately 0.25% in humans, demonstrating that highly polar triterpene glycosides are very poorly absorbed intact; this supports low F for the similarly large and polar query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Astragaloside IV, another triterpene saponin, has poor oral bioavailability in humans primarily due to very low solubility in biological fluids, supporting low F for the query with its very high molecular weight, TPSA, and hydrogen-bonding capacity.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is ginsenoside Rb1, a large tetraglycosylated triterpenoid. The closest analogue Rg3 has low human oral bioavailability, and multiple other triterpenoid glycosides (glycyrrhizin, astragaloside IV) show very low or poor oral absorption. Physicochemical properties (MW 1109, TPSA 377, 15 HBD, logD -2.2) strongly predict poor permeability and dissolution. Therefore, the prediction is low oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "Human data for the closest analogue Rg3 are qualitative rather than a precise F value.",
    "Possible gut-microbiota hydrolysis to an absorbable aglycone is not captured by intact bioavailability measurements.",
    "No evidence addresses prodrug behavior or active transporter-mediated absorption for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

